using System;using System.Windows;using System.Windows.Controls;using SAUDICO.Federate.ACC;using SAUDICO.Federate.Core.Models;using SAUDICO.Federate.Shared;namespace SAUDICO.Federate.UI;
public sealed class AccInputDialog:Window { readonly TextBox url=new(),project=new(),model=new();readonly ComboBox region=new(){ItemsSource=new[]{"EMEA","US"},SelectedIndex=0};public ModelInfo? Result{get;private set;}public AccInputDialog(){Title="Add ACC Model";Width=520;Height=350;var s=new StackPanel{Margin=new Thickness(20)};s.Children.Add(new TextBlock{Text="Autodesk Docs URL (optional)"});s.Children.Add(url);s.Children.Add(new TextBlock{Text="Project GUID"});s.Children.Add(project);s.Children.Add(new TextBlock{Text="Model GUID"});s.Children.Add(model);s.Children.Add(new TextBlock{Text="Region"});s.Children.Add(region);var b=new Button{Content="Add ACC Model",Margin=new Thickness(0,16,0,0)};b.Click+=(x,e)=>{Guid p,g;if(!string.IsNullOrWhiteSpace(url.Text)&&AccUrlParser.TryParse(url.Text,out p,out g)){project.Text=p.ToString();model.Text=g.ToString();}if(!Guid.TryParse(project.Text,out p)||!Guid.TryParse(model.Text,out g)){MessageBox.Show("Enter valid Project and Model GUIDs, or a URL containing both GUIDs.");return;}Result=new ModelInfo{Type=ModelType.ACC,FilePath=url.Text,ProjectGuid=p.ToString(),ModelGuid=g.ToString(),Region=region.SelectedIndex==1?CloudRegion.US:CloudRegion.EMEA};DialogResult=true;};s.Children.Add(b);Content=s;} }
